# In organizers/models.py
from django.db import models
from profiles.models import BusinessProfile
from tax.models import TaxYear

class OrganizerWorkbook(models.Model):
    business_profile = models.ForeignKey(BusinessProfile, on_delete=models.CASCADE, related_name='organizer_workbooks')
    tax_year = models.ForeignKey(TaxYear, on_delete=models.CASCADE, related_name='organizer_workbooks', null=True, blank=True)
    title = models.CharField(max_length=255)
    original_file = models.FileField(upload_to='organizers/originals/')
    upload_date = models.DateTimeField(auto_now_add=True)
    status = models.CharField(max_length=50, choices=[
        ('pending', 'Pending Processing'),
        ('processing', 'Processing'),
        ('completed', 'Completed'),
        ('failed', 'Failed')
    ], default='pending')
    notes = models.TextField(blank=True, null=True)

    def __str__(self):
        return f"{self.business_profile.name} - {self.title}"

class OrganizerOutput(models.Model):
    workbook = models.ForeignKey(OrganizerWorkbook, on_delete=models.CASCADE, related_name='outputs')
    output_type = models.CharField(max_length=50, choices=[
        ('thumbnail', 'Thumbnail'),
        ('page_pdf', 'Page PDF'),
        ('manifest', 'Manifest')
    ])
    file = models.FileField(upload_to='organizers/outputs/')
    page_number = models.IntegerField(null=True, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return f"{self.workbook.title} - {self.output_type} - {self.page_number or 'N/A'}"
```

2. Integrate with the existing Processing Tasks system:
```python
# In organizers/tasks.py
from celery import shared_task
from .models import OrganizerWorkbook, OrganizerOutput
import os
from django.conf import settings
import subprocess
import json

@shared_task
def process_organizer_workbook(workbook_id):
    workbook = OrganizerWorkbook.objects.get(id=workbook_id)
    workbook.status = 'processing'
    workbook.save()

    try:
        # Create output directory
        output_dir = os.path.join(settings.MEDIA_ROOT, f'organizers/outputs/{workbook_id}')
        os.makedirs(output_dir, exist_ok=True)

        # Process the workbook (example using a hypothetical PDF processing tool)
        input_path = workbook.original_file.path

        # Generate thumbnails
        thumbnail_output = os.path.join(output_dir, 'thumbnails')
        os.makedirs(thumbnail_output, exist_ok=True)
        subprocess.run(['pdf-tools', 'thumbnails', input_path, thumbnail_output])

        # Generate per-page PDFs
        pages_output = os.path.join(output_dir, 'pages')
        os.makedirs(pages_output, exist_ok=True)
        subprocess.run(['pdf-tools', 'split', input_path, pages_output])

        # Generate manifest
        manifest_path = os.path.join(output_dir, 'manifest.json')
        subprocess.run(['pdf-tools', 'manifest', input_path, manifest_path])

        # Save outputs to database
        # Thumbnails
        for filename in os.listdir(thumbnail_output):
            if filename.endswith('.jpg') or filename.endswith('.png'):
                page_num = int(filename.split('.')[0])
                rel_path = f'organizers/outputs/{workbook_id}/thumbnails/{filename}'
                OrganizerOutput.objects.create(
                    workbook=workbook,
                    output_type='thumbnail',
                    file=rel_path,
                    page_number=page_num
                )

        # Page PDFs
        for filename in os.listdir(pages_output):
            if filename.endswith('.pdf'):
                page_num = int(filename.split('.')[0])
                rel_path = f'organizers/outputs/{workbook_id}/pages/{filename}'
                OrganizerOutput.objects.create(
                    workbook=workbook,
                    output_type='page_pdf',
                    file=rel_path,
                    page_number=page_num
                )

        # Manifest
        rel_path = f'organizers/outputs/{workbook_id}/manifest.json'
        OrganizerOutput.objects.create(
            workbook=workbook,
            output_type='manifest',
            file=rel_path
        )

        workbook.status = 'completed'
        workbook.save()

    except Exception as e:
        workbook.status = 'failed'
        workbook.notes = f"Processing failed: {str(e)}"
        workbook.save()
        raise
```

