    actions = ['process_selected_workbooks']

    def process_selected_workbooks(self, request, queryset):
        from .tasks import process_organizer_workbook
        for workbook in queryset:
            process_organizer_workbook.delay(workbook.id)
        self.message_user(request, f"{queryset.count()} workbooks queued for processing.")
    process_selected_workbooks.short_description = "Process selected workbooks"
