5. Create views for uploading and managing workbooks:
```python
# In organizers/views.py
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from .models import OrganizerWorkbook, OrganizerOutput
from .forms import OrganizerWorkbookForm
from .tasks import process_organizer_workbook

@login_required
def upload_workbook(request):
    if request.method == 'POST':
        form = OrganizerWorkbookForm(request.POST, request.FILES)
        if form.is_valid():
            workbook = form.save()
            process_organizer_workbook.delay(workbook.id)
            messages.success(request, "Workbook uploaded and queued for processing.")
            return redirect('organizer_workbook_detail', pk=workbook.id)
    else:
        form = OrganizerWorkbookForm()

    return render(request, 'organizers/upload.html', {'form': form})

@login_required
def workbook_detail(request, pk):
    workbook = get_object_or_404(OrganizerWorkbook, pk=pk)
    outputs = workbook.outputs.all().order_by('output_type', 'page_number')

    return render(request, 'organizers/detail.html', {
        'workbook': workbook,
        'outputs': outputs
    })

@login_required
def attach_to_binder(request, pk):
    workbook = get_object_or_404(OrganizerWorkbook, pk=pk)

    if request.method == 'POST':
        tax_year_id = request.POST.get('tax_year')
        if tax_year_id:
            from tax.models import TaxYear
            tax_year = get_object_or_404(TaxYear, pk=tax_year_id)
            workbook.tax_year = tax_year
            workbook.save()
            messages.success(request, f"Workbook attached to {tax_year.business_profile.name} - {tax_year.year}")
            return redirect('organizer_workbook_detail', pk=workbook.id)

    # Get available tax years
    from tax.models import TaxYear
    tax_years = TaxYear.objects.all().order_by('-year')

    return render(request, 'organizers/attach_to_binder.html', {
        'workbook': workbook,
        'tax_years': tax_years
    })
```

